def _astral(key: str) -> str:
    i = 0
    while i < len(_AN):
        if _AN[i] == key:
            return chr(_AC[i])
        i = i + 1
    return ''


class _Html5Table:
    """html5 as a read-only mapping: BMP values are exact, astral values are built lazily."""

    def __init__(self) -> None:
        self.ready: int = 1

    def __len__(self) -> int:
        return len(_BMP5) + len(_AN)

    def __contains__(self, key: str) -> bool:
        if key in _BMP5:
            return True
        return _astral(key) != ''

    def __getitem__(self, key: str) -> str:
        if key in _BMP5:
            return _BMP5[key]
        value = _astral(key)
        if value != '':
            return value
        raise KeyError(key)

    def get(self, key: str, default=None):
        if key in _BMP5:
            return _BMP5[key]
        value = _astral(key)
        if value != '':
            return value
        return default


